def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    result = []
    i = 0
    n = len(template)

    while i < n:
        c = template[i]
        if c == '{':
            if i + 1 < n and template[i + 1] == '{':
                result.append('{')
                i += 2
            else:
                start = i
                i += 1
                if i >= n:
                    raise ValueError(
                        f"unclosed placeholder at position {start}"
                    )
                name_chars = []
                while i < n and template[i] != '}':
                    ch = template[i]
                    if not (
                        ch == '_'
                        or 'A' <= ch <= 'Z'
                        or 'a' <= ch <= 'z'
                        or '0' <= ch <= '9'
                    ):
                        raise ValueError(
                            f"invalid placeholder at position {start}"
                        )
                    name_chars.append(ch)
                    i += 1
                if i >= n:
                    raise ValueError(
                        f"unclosed placeholder at position {start}"
                    )
                if not name_chars:
                    raise ValueError(
                        f"empty placeholder at position {start}"
                    )
                name = ''.join(name_chars)
                if name not in context:
                    raise KeyError(name)
                result.append(str(context[name]))
                i += 1
        elif c == '}':
            if i + 1 < n and template[i + 1] == '}':
                result.append('}')
                i += 2
            else:
                raise ValueError(f"stray '}}' at position {i}")
        else:
            result.append(c)
            i += 1

    return ''.join(result)

def deep_get(data, path):
    def all_digits(s):
        if s == "":
            return True
        if not ("0" <= s[0] <= "9"):
            return False
        return all_digits(s[1:])

    def is_valid_int_literal(s):
        if s == "" or s == "-":
            return False
        if s[0] == "-":
            return all_digits(s[1:])
        return all_digits(s)

    def traverse(node, segments):
        if len(segments) == 0:
            return node
        segment = segments[0]
        rest = segments[1:]
        if isinstance(node, dict):
            if segment not in node:
                raise KeyError(segment)
            return traverse(node[segment], rest)
        if isinstance(node, list):
            if not is_valid_int_literal(segment):
                raise ValueError("invalid index")
            index = int(segment)
            if index >= len(node) or index < -len(node):
                raise IndexError(segment)
            return traverse(node[index], rest)
        raise TypeError("cannot descend")

    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")
    segments = path.split(".")
    if "" in segments:
        raise ValueError("empty segment")
    return traverse(data, segments)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if not tokens:
        raise ValueError("empty expression")

    stack = []
    operators = {"+", "-", "*", "/"}

    for i, token in enumerate(tokens):
        if not isinstance(token, str):
            raise TypeError(f"token {i}")

        if token in operators:
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            else:
                if right == 0:
                    raise ZeroDivisionError(f"token {i}")
                abs_result = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    result = -abs_result
                else:
                    result = abs_result
            stack.append(result)
        else:
            if not token:
                raise ValueError(f"unknown token at token {i}")
            start = 0
            if token[0] in "+-":
                start = 1
            if start >= len(token) or not all("0" <= c <= "9" for c in token[start:]):
                raise ValueError(f"unknown token at token {i}")
            stack.append(int(token))

    if len(stack) > 1:
        raise ValueError("leftover operands")
    return stack[0]

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")
    result = {}
    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i}")
        category, amount, refunded = row
        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i}")
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i}")
        if amount < 0:
            raise ValueError(f"row {i}")
        if not isinstance(refunded, bool):
            raise TypeError(f"row {i}")
        amt = float(amount)
        if category not in result:
            result[category] = {
                "count": 0,
                "gross": 0.0,
                "net": 0.0,
                "largest": amt,
            }
        summary = result[category]
        summary["count"] += 1
        summary["gross"] += amt
        if not refunded:
            summary["net"] += amt
        if amt > summary["largest"]:
            summary["largest"] = amt
    return result

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")
    if k == 0:
        return []

    counts = {}
    order = []
    for item in items:
        if item not in counts:
            counts[item] = 0
            order.append(item)
        counts[item] += 1

    remaining = order[:]
    result = []
    n = len(remaining)
    limit = k if k < n else n
    for _ in range(limit):
        best_idx = 0
        best_item = remaining[0]
        best_count = counts[best_item]
        for i in range(1, len(remaining)):
            item = remaining[i]
            cnt = counts[item]
            if cnt > best_count:
                best_count = cnt
                best_item = item
                best_idx = i
        result.append((best_item, best_count))
        del remaining[best_idx]
    return result

import heapq

def max_bounty(jobs: list[tuple[int, int]], cap: int) -> int:
    if cap < 1:
        raise ValueError
    if not jobs:
        return 0
    jobs = sorted(jobs)
    heap = []
    total = 0
    for d, p in jobs:
        max_jobs = cap * d
        if len(heap) < max_jobs:
            heapq.heappush(heap, p)
            total += p
        elif p > heap[0]:
            total += p - heap[0]
            heapq.heapreplace(heap, p)
    return total

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")
    if text.strip() == "":
        raise ValueError("empty duration")
    total = 0
    i = 0
    n = len(text)
    prev = -1
    while i < n:
        if not text[i].isdigit():
            raise ValueError("malformed duration")
        j = i
        while j < n and text[j].isdigit():
            j += 1
        num = int(text[i:j])
        i = j
        if i >= n:
            raise ValueError("malformed duration")
        unit = text[i]
        i += 1
        if unit == 'h':
            u = 0
            mult = 3600
        elif unit == 'm':
            u = 1
            mult = 60
        elif unit == 's':
            u = 2
            mult = 1
        else:
            raise ValueError("malformed duration")
        if u <= prev:
            raise ValueError("malformed duration")
        prev = u
        total += num * mult
    return total

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    stack = [(nested, 0, max_depth)]
    while stack:
        current_list, idx, depth = stack[-1]
        if idx >= len(current_list):
            stack.pop()
            continue
        item = current_list[idx]
        stack[-1] = (current_list, idx + 1, depth)
        if isinstance(item, list) and depth > 0:
            stack.append((item, 0, depth - 1))
        else:
            result.append(item)
    return result

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if (isinstance(low, bool) or isinstance(high, bool) or
            not isinstance(low, (int, float)) or
            not isinstance(high, (int, float))):
        raise TypeError("bounds must be numbers")
    if low > high:
        raise ValueError("low must not exceed high")
    result = []
    for i, x in enumerate(values):
        if isinstance(x, bool) or not isinstance(x, (int, float)):
            raise TypeError(f"index {i}")
        if x < low:
            result.append(low)
        elif x > high:
            result.append(high)
        else:
            result.append(x)
    return result

def longest_echo(s: str) -> int:
    n = len(s)
    if n <= 1:
        return 0

    MOD1 = 1_000_000_007
    MOD2 = 1_000_000_009
    BASE = 911_382_323

    def has_repeat(L: int) -> bool:
        if L == 0:
            return True
        if L >= n:
            return False
        h1 = 0
        h2 = 0
        power1 = 1
        power2 = 1
        for i in range(L):
            h1 = (h1 * BASE + ord(s[i])) % MOD1
            h2 = (h2 * BASE + ord(s[i])) % MOD2
            if i < L - 1:
                power1 = (power1 * BASE) % MOD1
                power2 = (power2 * BASE) % MOD2
        seen = {(h1, h2)}
        for i in range(1, n - L + 1):
            h1 = (h1 - ord(s[i - 1]) * power1) % MOD1
            h1 = (h1 * BASE + ord(s[i + L - 1])) % MOD1
            h2 = (h2 - ord(s[i - 1]) * power2) % MOD2
            h2 = (h2 * BASE + ord(s[i + L - 1])) % MOD2
            key = (h1, h2)
            if key in seen:
                return True
            seen.add(key)
        return False

    lo, hi = 1, n - 1
    ans = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if has_repeat(mid):
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

class MergeLedger:
    def __init__(self):
        self.parent = {}
        self.size = {}
        self.sum = {}
        self.value = {}
        self.history = []
        self.num = 0

    def _find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def add(self, x, value=0):
        if x in self.value:
            raise ValueError(x)
        self.value[x] = value
        self.parent[x] = x
        self.size[x] = 1
        self.sum[x] = value
        self.num += 1

    def merge(self, a, b):
        if a not in self.value or b not in self.value:
            raise KeyError
        ra = self._find(a)
        rb = self._find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.sum[ra] += self.sum[rb]
        self.history.append(rb)
        self.num -= 1
        return True

    def same(self, a, b):
        if a not in self.value or b not in self.value:
            raise KeyError
        return self._find(a) == self._find(b)

    def component_size(self, x):
        if x not in self.value:
            raise KeyError
        return self.size[self._find(x)]

    def component_value(self, x):
        if x not in self.value:
            raise KeyError
        return self.sum[self._find(x)]

    def add_value(self, x, delta):
        if x not in self.value:
            raise KeyError
        self.value[x] += delta
        cur = x
        while True:
            self.sum[cur] += delta
            if self.parent[cur] == cur:
                break
            cur = self.parent[cur]

    def components(self):
        return self.num

    def undo(self):
        if not self.history:
            raise RuntimeError
        small = self.history.pop()
        large = self.parent[small]
        self.parent[small] = small
        self.sum[large] -= self.sum[small]
        self.size[large] -= self.size[small]
        self.num += 1

def peak_load(intervals: list[tuple[int, int]]) -> tuple[int, int]:
    events = [(s, 1) for s, e in intervals] + [(e, -1) for s, e in intervals]
    events.sort()  # sorts by time ascending, then delta (-1 before +1)
    current = 0
    max_load = 0
    earliest = 0
    for t, d in events:
        current += d
        if current > max_load:
            max_load = current
            earliest = t
    return (max_load, earliest)

def kth_root_floor(n: int, k: int) -> int:
    if n < 0 or k < 1:
        raise ValueError
    if k == 1:
        return n
    if n == 0 or n == 1:
        return n

    # binary search for largest r >= 1 such that r**k <= n
    low = 1
    high = n
    while low < high:
        mid = (low + high + 1) // 2
        if mid ** k <= n:
            low = mid
        else # mid**k > n
            high = mid - 1
    return low

def count_locked_pairs(values: list[int], m: int) -> int:
    if m < 1:
        raise ValueError
    even = [0] * m
    odd = [0] * m
    for v in values:
        r = v % m
        if v % 2 == 0:
            even[r] += 1
        else:
            odd[r] += 1
    count = 0
    for r in range(m):
        s = (m - r) % m
        if r < s:
            count += even[r] * even[s] + odd[r] * odd[s]
        elif r == s:
            e = even[r]
            o = odd[r]
            count += e * (e - 1) // 2 + o * (o - 1) // 2
    return count

from collections import deque

def count_stable_windows(readings: list[int], tol: int) -> int:
    n = len(readings)
    if n == 0:
        return 0
    minq = deque()  # indices, readings increasing
    maxq = deque()  # indices, readings decreasing
    left = 0
    count = 0
    for right in range(n):
        while minq and readings[minq[-1]] >= readings[right]:
            minq.pop()
        minq.append(right)
        while maxq and readings[maxq[-1]] <= readings[right]:
            maxq.pop()
        maxq.append(right)
        while readings[maxq[0]] - readings[minq[0]] > tol:
            left += 1
            if minq[0] < left:
                minq.popleft()
            if maxq[0] < left:
                maxq.popleft()
        count += right - left + 1
    return count

def round_robin(iterables):
    iterators = [iter(it) for it in iterables]
    while iterators:
        remaining = []
        for it in iterators:
            try:
                yield next(it)
                remaining.append(it)
            except StopIteration:
                pass
        iterators = remaining

import math

def vector_norm(v: list[float]) -> float:
    if any(math.isnan(x) or math.isinf(x) for x in v):
        raise ValueError("vector contains NaN or infinity")
    if not v:
        return 0.0
    max_abs = max(abs(x) for x in v)
    if max_abs == 0.0:
        return 0.0
    sum_sq = sum((x / max_abs) ** 2 for x in v)
    return max_abs * math.sqrt(sum_sq)

def weighted_median(values: list, weights: list) -> float:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    W = sum(weights)
    if W <= 0:
        raise ValueError("total weight must be positive")
    pairs = sorted(zip(values, weights), key=lambda p: p[0])
    thresh = W / 2 - 1e-9
    cum = 0.0
    for v, w in pairs:
        cum += w
        if cum >= thresh:
            return float(v)
    # Unreachable when W > 0
    raise ValueError("no median found")

import unicodedata

def truncate_display(s: str, width: int) -> str:
    if width < 0:
        raise ValueError
    if width == 0 or not s:
        return ""

    def is_combining(ch: str) -> bool:
        return unicodedata.category(ch) in ("Mn", "Mc", "Me")

    units = []
    i = 0
    n = len(s)
    while i < n:
        unit = [s[i]]
        i += 1
        while i < n and is_combining(s[i]):
            unit.append(s[i])
            i += 1
        units.append("".join(unit))

    if width >= len(units):
        return s
    return "".join(units[:width])

def rank_scores(scores: list) -> list[int]:
    for s in scores:
        if s != s:  # NaN check
            raise ValueError("NaN scores are not allowed")
    sorted_desc = sorted(scores, reverse=True)
    rank_of = {}
    for i, s in enumerate(sorted_desc):
        if s not in rank_of:
            rank_of[s] = i + 1
    return [rank_of[s] for s in scores]

class IntervalSet:
    def __init__(self):
        self._iv = []  # sorted list of disjoint non-adjacent (lo, hi) tuples

    def add(self, lo, hi):
        if lo >= hi:
            raise ValueError
        left = 0
        while left < len(self._iv) and self._iv[left][1] < lo:
            left += 1
        right = left
        while right < len(self._iv) and self._iv[right][0] <= hi:
            right += 1
        new_lo, new_hi = lo, hi
        if left < right:
            new_lo = min(new_lo, self._iv[left][0])
            new_hi = max(new_hi, self._iv[right - 1][1])
        self._iv[left:right] = [(new_lo, new_hi)]

    def remove(self, lo, hi):
        if lo >= hi:
            raise ValueError
        left = 0
        while left < len(self._iv) and self._iv[left][1] <= lo:
            left += 1
        right = left
        while right < len(self._iv) and self._iv[right][0] < hi:
            right += 1
        new_parts = []
        if left < right:
            if self._iv[left][0] < lo:
                new_parts.append((self._iv[left][0], lo))
            if self._iv[right - 1][1] > hi:
                new_parts.append((hi, self._iv[right - 1][1]))
        self._iv[left:right] = new_parts

    def contains(self, x):
        lo, hi = 0, len(self._iv)
        while lo < hi:
            mid = (lo + hi) // 2
            if self._iv[mid][0] <= x:
                lo = mid + 1
            else:
                hi = mid
        i = lo - 1
        return i >= 0 and self._iv[i][1] > x

    def total(self):
        return sum(hi - lo for lo, hi in self._iv)

    def intervals(self):
        return list(self._iv)

    def gaps(self, lo, hi):
        if lo >= hi:
            raise ValueError
        left = 0
        while left < len(self._iv) and self._iv[left][1] <= lo:
            left += 1
        right = left
        while right < len(self._iv) and self._iv[right][0] < hi:
            right += 1
        result = []
        current = lo
        for i in range(left, right):
            a, b = self._iv[i]
            if a > current:
                result.append((current, min(a, hi)))
            current = max(current, b)
            if current >= hi:
                break
        if current < hi:
            result.append((current, hi))
        return result

import heapq

class TaskScheduler:
    def __init__(self):
        self._time = 0
        self._active = {}  # task_id -> (priority, submission_time)
        self._heap = []    # entries: (-priority, submission_time, task_id)

    def submit(self, task_id, priority):
        if task_id in self._active:
            raise ValueError("task already active")
        self._time += 1
        self._active[task_id] = (priority, self._time)
        heapq.heappush(self._heap, (-priority, self._time, task_id))

    def reprioritize(self, task_id, priority):
        if task_id not in self._active:
            raise KeyError(task_id)
        _, sub_time = self._active[task_id]
        self._active[task_id] = (priority, sub_time)
        heapq.heappush(self._heap, (-priority, sub_time, task_id))

    def cancel(self, task_id):
        if task_id not in self._active:
            raise KeyError(task_id)
        del self._active[task_id]

    def _clean(self):
        while self._heap:
            neg_p, t, tid = self._heap[0]
            if tid in self._active and self._active[tid] == (-neg_p, t):
                return
            heapq.heappop(self._heap)

    def pop(self):
        self._clean()
        if not self._heap:
            raise IndexError("pop from empty scheduler")
        _, _, tid = heapq.heappop(self._heap)
        del self._active[tid]
        return tid

    def peek(self):
        self._clean()
        if not self._heap:
            raise IndexError("peek from empty scheduler")
        return self._heap[0][2]

    def priority_of(self, task_id):
        if task_id not in self._active:
            raise KeyError(task_id)
        return self._active[task_id][0]

    def __len__(self):
        return len(self._active)

class Leaderboard:
    def __init__(self):
        self._best = {}          # player -> (best_score, achievement_time)
        self._clock = 0

    def submit(self, player, score):
        if player not in self._best or score > self._best[player][0]:
            self._best[player] = (score, self._clock)
            self._clock += 1
            return True
        return False

    def best(self, player):
        return self._best[player][0]

    def rank(self, player):
        my_score = self._best[player][0]
        better = sum(1 for s, _ in self._best.values() if s > my_score)
        return better + 1

    def top(self, k):
        if k < 0:
            raise ValueError
        ordered = sorted(
            self._best.items(),
            key=lambda item: (-item[1][0], item[1][1])
        )
        return [(p, s) for p, (s, _) in ordered[:k]]

    def player_count(self):
        return len(self._best)

class VersionedKV:
    """Key-value store with commit snapshots, point-in-time reads, and rollback."""

    def __init__(self):
        self._working = {}
        self._history = []  # history[i] is the snapshot for version i + 1

    def set(self, key, value) -> None:
        self._working[key] = value

    def delete(self, key) -> None:
        if key not in self._working:
            raise KeyError(key)
        del self._working[key]

    def get(self, key):
        if key not in self._working:
            raise KeyError(key)
        return self._working[key]

    def has(self, key) -> bool:
        return key in self._working

    def commit(self) -> int:
        # Shallow copy: later set/delete on working state cannot alter snapshots.
        self._history.append(dict(self._working))
        return len(self._history)

    def latest(self) -> int:
        return len(self._history)

    def get_at(self, key, version):
        if not (1 <= version <= self.latest()):
            raise ValueError(
                f"version must satisfy 1 <= version <= {self.latest()}, got {version}"
            )
        snapshot = self._history[version - 1]
        if key not in snapshot:
            raise KeyError(key)
        return snapshot[key]

    def rollback(self, version) -> None:
        if not (0 <= version <= self.latest()):
            raise ValueError(
                f"version must satisfy 0 <= version <= {self.latest()}, got {version}"
            )
        if version == 0:
            self._working = {}
        else:
            # Copy so subsequent mutations do not alter the stored snapshot.
            self._working = dict(self._history[version - 1])

import collections

class TTLCache:
    def __init__(self, capacity):
        if type(capacity) is not int or capacity < 1:
            raise ValueError
        self.capacity = capacity
        self.cache = collections.OrderedDict()  # key -> (value, stored_time, ttl)
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def _purge(self, now):
        expired = [k for k, (_, t, ttl) in self.cache.items()
                   if ttl is not None and now >= t + ttl]
        for k in expired:
            del self.cache[k]
            self.expirations += 1

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError
        self._purge(now)
        if key in self.cache:
            self.cache[key] = (value, now, ttl)
            self.cache.move_to_end(key)
        else:
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
                self.evictions += 1
            self.cache[key] = (value, now, ttl)

    def get(self, key, now):
        self._purge(now)
        if key in self.cache:
            self.hits += 1
            self.cache.move_to_end(key)
            return self.cache[key][0]
        self.misses += 1
        return None

    def stats(self):
        return {
            "hits": self.hits,
            "misses": self.misses,
            "evictions": self.evictions,
            "expirations": self.expirations,
        }

    def __len__(self):
        return len(self.cache)

class CountingBag:
    def __init__(self):
        self._counts = {}
        self._entry = {}
        self._time = 0
        self._total = 0

    def add(self, item):
        if item not in self._counts:
            self._entry[item] = self._time
            self._time += 1
            self._counts[item] = 1
        else:
            self._counts[item] += 1
        self._total += 1
        return self._counts[item]

    def discard(self, item):
        if item not in self._counts:
            return False
        self._counts[item] -= 1
        self._total -= 1
        if self._counts[item] == 0:
            del self._counts[item]
            del self._entry[item]
        return True

    def count(self, item):
        return self._counts.get(item, 0)

    def __len__(self):
        return self._total

    def distinct(self):
        return len(self._counts)

    def most_common(self, k):
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        items = list(self._counts.items())
        items.sort(key=lambda x: (-x[1], self._entry[x[0]]))
        return items[:k]

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        if ordered[i][0] < prev[0] + prev[1] or ordered[i][0] == prev[0]:
            raise ValueError("conflicting hunks")
    result = list(lines)
    for start, delete, insert in reversed(ordered):
        if start < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")
        result[start:start + delete] = list(insert)
    return result

import heapq
from collections import defaultdict

def min_cost_route(n, edges, s, t, switch_cost):
    if s == t:
        return 0

    INF = 10 ** 18
    # adj[u][color] = list of (v, w)
    adj = [defaultdict(list) for _ in range(n)]
    for u, v, w, color in edges:
        adj[u][color].append((v, w))
        if u != v:
            adj[v][color].append((u, w))

    # dist[u][color] = min cost to reach u via an edge of that color
    dist = [dict() for _ in range(n)]
    # dist_sw[u] = min cost to reach u and pay for a color switch (ready to take any next edge)
    dist_sw = [INF] * n
    SENT = ''  # sentinel for the "switched" state (colors are non-empty)

    pq = []  # (cost, node, color_or_SENT)
    dist_sw[s] = 0
    heapq.heappush(pq, (0, s, SENT))

    while pq:
        cost, u, c = heapq.heappop(pq)
        if c == SENT:
            if cost > dist_sw[u]:
                continue
            # From the switched state take every outgoing edge (switch already paid)
            for color, elist in adj[u].items():
                for v, w in elist:
                    newcost = cost + w
                    if newcost < dist[v].get(color, INF):
                        dist[v][color] = newcost
                        heapq.heappush(pq, (newcost, v, color))
        else:
            if cost > dist[u].get(c, INF):
                continue
            # Continue with the same color (no switch fee)
            for v, w in adj[u][c]:
                newcost = cost + w
                if newcost < dist[v].get(c, INF):
                    dist[v][c] = newcost
                    heapq.heappush(pq, (newcost, v, c))
            # Pay the switch fee and enter the switched state
            new_sw = cost + switch_cost
            if new_sw < dist_sw[u]:
                dist_sw[u] = new_sw
                heapq.heappush(pq, (new_sw, u, SENT))

    if not dist[t]:
        return -1
    ans = min(dist[t].values())
    return ans if ans < INF else -1

class UndoStack:
    def __init__(self):
        self._stack = []
        self._history = []

    def push(self, x):
        self._stack.append(x)
        self._history.append(('push',))

    def pop(self):
        if not self._stack:
            raise IndexError
        value = self._stack.pop()
        self._history.append(('pop', value))
        return value

    def peek(self):
        if not self._stack:
            raise IndexError
        return self._stack[-1]

    def undo(self):
        if not self._history:
            raise RuntimeError
        op = self._history.pop()
        if op[0] == 'push':
            self._stack.pop()
        else:  # 'pop'
            self._stack.append(op[1])

    def __len__(self):
        return len(self._stack)

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)
    order = []
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        if node in visited:
            return
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        if node not in visited:
            visit(node)
    return order

def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        if "." in amount:
            parts = amount.split(".")
            if len(parts) != 2:
                raise ValueError("invalid amount")
            int_part, dec_part = parts
            if (not int_part or not int_part.isdigit() or
                    not dec_part.isdigit() or len(dec_part) not in (1, 2)):
                raise ValueError("invalid amount")
            cents = int(int_part) * 100 + int(dec_part) * (10 if len(dec_part) == 1 else 1)
        else:
            if not amount or not amount.isdigit():
                raise ValueError("invalid amount")
            cents = int(amount) * 100
        if cents <= 0:
            raise ValueError("amount must be positive")
        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents
    return balances

def insert_booking(bookings, new):
    start, end = new
    if start >= end:
        raise ValueError("empty booking")
    result = []
    i = 0
    while i < len(bookings) and bookings[i][1] <= start:
        result.append(bookings[i])
        i += 1
    while i < len(bookings) and bookings[i][0] < end:
        start = min(start, bookings[i][0])
        end = max(end, bookings[i][1])
        i += 1
    result.append((start, end))
    result.extend(bookings[i:])
    return result

from collections import deque, defaultdict
from math import inf

def min_steps(grid, c):
    R, C = len(grid), len(grid[0])
    if grid[0][0] == -1 or grid[R-1][C-1] == -1:
        return -1

    def bfs(sr, sc):
        dist = [[inf] * C for _ in range(R)]
        dist[sr][sc] = 0
        q = deque([(sr, sc)])
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        while q:
            r, col = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, col + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != -1 and dist[nr][nc] == inf:
                    dist[nr][nc] = dist[r][col] + 1
                    q.append((nr, nc))
        return dist

    ds = bfs(0, 0)
    de = bfs(R - 1, C - 1)
    min_cost = ds[R - 1][C - 1]

    groups = defaultdict(list)
    for r in range(R):
        for col in range(C):
            if grid[r][col] != -1:
                groups[grid[r][col]].append((r, col))

    for cells in groups.values():
        min_de = inf
        second_de = inf
        min_de_pos = None
        for r, col in cells:
            d = de[r][col]
            if d < inf:
                if d < min_de:
                    second_de = min_de
                    min_de = d
                    min_de_pos = (r, col)
                elif d < second_de:
                    second_de = d

        for r, col in cells:
            dsa = ds[r][col]
            if dsa < inf:
                if (r, col) != min_de_pos:
                    sumd = dsa + min_de
                else:
                    sumd = dsa + second_de
                if sumd < inf:
                    min_cost = min(min_cost, sumd + c)

    return min_cost if min_cost < inf else -1

def purge_expired(sessions, now):
    purged = [sid for sid, expiry in sessions.items() if expiry <= now]
    for sid in purged:
        del sessions[sid]
    return purged

def merge_settings(defaults, overrides):
    result = dict(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_settings(result[key], value)
        else:
            result[key] = value
    return result

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

def longest_spaced_repeat(s, gap):
    n = len(s)
    if n == 0:
        return 0
    # lcp[i][j] = length of longest common prefix of s[i:] and s[j:]
    lcp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if s[i] == s[j]:
                lcp[i][j] = 1 + lcp[i + 1][j + 1]
    max_L = 0
    for p in range(n):
        for q in range(p + 1, n):
            max_possible = q - p - gap
            if max_possible < 1:
                continue
            L = min(lcp[p][q], max_possible, n - q)
            if L > max_L:
                max_L = L
    return max_L

def smallest_balanced(s):
    n = len(s)
    if n % 2 != 0:
        raise ValueError
    needed = n // 2
    open_fixed = s.count('(')
    q = s.count('?')
    if open_fixed > needed or open_fixed + q < needed:
        raise ValueError
    needed_q_open = needed - open_fixed
    res = []
    for c in s:
        if c == '?':
            if needed_q_open > 0:
                res.append('(')
                needed_q_open -= 1
            else:
                res.append(')')
        else:
            res.append(c)
    bal = 0
    for c in res:
        bal += 1 if c == '(' else -1
        if bal < 0:
            raise ValueError
    return ''.join(res)

def max_sum_linear(arr, k):
    if k == 0:
        return 0
    m = len(arr)
    NEG_INF = -10**18
    dp = [[NEG_INF] * (k + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = 0
    for i in range(1, m + 1):
        for j in range(1, k + 1):
            skip = dp[i - 1][j]
            if i == 1:
                take_base = 0 if j == 1 else NEG_INF
            else:
                take_base = dp[i - 2][j - 1]
            take = take_base + arr[i - 1]
            dp[i][j] = max(skip, take)
    return dp[m][k]


def best_circular_selection(values, k):
    n = len(values)
    if k == 0:
        return 0
    if n == 1:
        return values[0]
    if k > n // 2:
        raise ValueError
    res1 = max_sum_linear(values[1:], k)
    res2 = max_sum_linear(values[:-1], k)
    return max(res1, res2)

def max_sessions(intervals, gap):
    if not intervals:
        return 0
    intervals = sorted(intervals, key=lambda x: x[1])
    count = 0
    last_end = float('-inf')
    for start, end in intervals:
        if start >= last_end + gap:
            count += 1
            last_end = end
    return count
